"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[7017],{8973(e,t,a){a.r(t),a.d(t,{assets:()=>p,contentTitle:()=>d,default:()=>u,frontMatter:()=>l,metadata:()=>n,toc:()=>c});const n=JSON.parse('{"id":"part4-ml-foundations/index","title":"Part IV \u2014 ML Foundations","description":"The geometric, code\u2011first foundations every later chapter depends on. We start with tensors, autograd, modules, and the training loop, then ask \u201cwhat is a model, geometrically?\u201d We implement linear regression and clas...","source":"@site/docs/part4-ml-foundations/index.mdx","sourceDirName":"part4-ml-foundations","slug":"/part4-ml-foundations/overview","permalink":"/tutorials/part4-ml-foundations/overview","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"frontMatter":{"title":"Part IV \u2014 ML Foundations","slug":"/part4-ml-foundations/overview","description":"The geometric, code\u2011first foundations every later chapter depends on. We start with tensors, autograd, modules, and the training loop, then ask \u201cwhat is a model, geometrically?\u201d We implement linear regression and clas...","sidebar_label":"Part overview","pagination_label":"Part overview","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"7. LangChain, LangGraph, and Flowise","permalink":"/tutorials/part3-agent-protocols/07-langchain-langgraph-flowise"},"next":{"title":"1. PyTorch foundations","permalink":"/tutorials/part4-ml-foundations/01-introduction-pytorch"}}');var o=a(4848),r=a(8453),i=a(8172);const s=JSON.parse('{"sourcePath":"part4-ml-foundations/index.html","route":"/part4-ml-foundations/overview","kind":"part","partId":"part4","partLabel":"Part IV - Machine Learning Foundations","accent":"amber","heading":"Part IV \u2014 ML Foundations","title":"Part IV \u2014 ML Foundations","description":"The geometric, code\u2011first foundations every later chapter depends on. We start with tensors, autograd, modules, and the training loop, then ask \u201cwhat is a model, geometrically?\u201d We implement linear regression and clas...","readingMinutes":1,"bodyClass":"","normalizeMath":false,"toc":[{"id":"chapters-in-order","label":"Chapters in order"}],"html":"<p>The geometric, code\u2011first foundations every later chapter depends on. We\\nstart with tensors, autograd, modules, and the training loop, then ask \u201cwhat\\nis a model, geometrically?\u201d We implement linear regression and classification\\nend-to-end in PyTorch before covering the tree/ensemble\\nfamily (Random Forest, AdaBoost, Gradient Boosting, XGBoost) \u2014 the family\\nthat still beats deep learning on tabular data.</p>\\n\\n<div class=\\"tr-note\\">\\n  <strong>Prerequisites</strong>\\n  Python 3 fluency, basic linear algebra (vectors, matrix multiply,\\n  derivatives). No prior PyTorch needed \u2014 Chapter 1 is the on\u2011ramp. Read\\n  this part <em>before</em> Part V (Deep Learning &amp; LLMs).\\n</div>\\n\\n<div class=\\"tr-tip\\">\\n  <strong>What you can do after this part</strong>\\n  Train and evaluate a regression or classification model in PyTorch from\\n  scratch, and ship a tabular ML baseline using XGBoost. You can then\\n  proceed to <a href=\\"/tutorials/part5-deep-learning-and-llms/overview\\">Part V</a>\\n  with no gaps.\\n</div>\\n\\n<div class=\\"tr-note\\">\\n  <strong>ML foundations spine</strong>\\n  Chapter 2 is the conceptual foundation: data points, model shapes, regression,\\n  classification, and supervised learning. Chapters 3 and 4 intentionally\\n  repeat the same fit/predict/score workflow because regression and\\n  classification differ in target type, output activation, loss, and metrics.\\n  Chapter 5 then branches to tree and ensemble methods as the tabular baseline\\n  family that often competes with or beats neural networks on structured data.\\n</div>\\n\\n<h2 id=\\"chapters-in-order\\">Chapters in order</h2>\\n<ol>\\n  <li><a href=\\"/tutorials/part4-ml-foundations/01-introduction-pytorch\\">PyTorch foundations: tensors, autograd, modules, and training</a></li>\\n  <li><a href=\\"/tutorials/part4-ml-foundations/02-ml-as-geometry\\">Machine learning as geometry</a></li>\\n  <li><a href=\\"/tutorials/part4-ml-foundations/03-linear-regression\\">Linear regression and the training loop</a></li>\\n  <li><a href=\\"/tutorials/part4-ml-foundations/04-linear-classification\\">Linear classification (logistic regression)</a></li>\\n  <li><a href=\\"/tutorials/part4-ml-foundations/05-trees-bagging-boosting\\">Trees, bagging &amp; boosting (Random Forest, AdaBoost, XGBoost)</a></li>\\n</ol>"}'),l={title:"Part IV \u2014 ML Foundations",slug:"/part4-ml-foundations/overview",description:"The geometric, code\u2011first foundations every later chapter depends on. We start with tensors, autograd, modules, and the training loop, then ask \u201cwhat is a model, geometrically?\u201d We implement linear regression and clas...",sidebar_label:"Part overview",pagination_label:"Part overview",hide_title:!0,hide_table_of_contents:!0},d=void 0,p={},c=[];function h(e){return(0,o.jsx)(i.A,{content:s})}function u(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(h,{...e})}):h()}}}]);